const TArray<FGFBeatmap>& FGFBuiltInSongs::All()
{
	static const TArray<FGFBeatmap> Maps = []()
	{
		TArray<FGFBeatmap> Out;
		for (const TCHAR* Json : GFBuiltInSongData::Charts)
		{
			FGFBeatmap Map;
			FString Error;
			if (FGFBeatmapIO::FromJson(Json, Map, Error))
			{
				Out.Add(MoveTemp(Map));
			}
			else
			{
				UE_LOG(LogGF, Error, TEXT("Built-in beatmap failed to parse: %s"), *Error);
			}
		}
		return Out;
	}();
	return Maps;
}

int32 FGFBuiltInSongs::NumEmbeddedCharts()
{
	return UE_ARRAY_COUNT(GFBuiltInSongData::Charts);
}

const FGFBeatmap* FGFBuiltInSongs::Find(FName SongId, EGFBeatDifficulty Difficulty)
{
	for (const FGFBeatmap& Map : All())
	{
		if (Map.SongId == SongId && Map.Difficulty == Difficulty)
		{
			return &Map;
		}
	}
	return nullptr;
}

TArray<FName> FGFBuiltInSongs::SongIds()
{
	TArray<FName> Ids;
	for (const FGFBeatmap& Map : All())
	{
		Ids.AddUnique(Map.SongId);
	}
	return Ids;
}
